import{_ as t,r as a,o as c,c as o,e as n,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Хеширование и шифрование - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Конфигурация","slug":"конфигурация","link":"#конфигурация","children":[]},{"level":2,"title":"Хеширование","slug":"хеширование","link":"#хеширование","children":[{"level":4,"title":"Проверка пароля по хешу","slug":"проверка-пароля-по-хешу","link":"#проверка-пароля-по-хешу","children":[]},{"level":4,"title":"Проверка необходимости повторного хеширования пароля","slug":"проверка-необходимости-повторного-хеширования-пароля","link":"#проверка-необходимости-повторного-хеширования-пароля","children":[]}]},{"level":2,"title":"Шифрование","slug":"шифрование","link":"#шифрование","children":[{"level":4,"title":"Расшифровка значения","slug":"расшифровка-значения","link":"#расшифровка-значения","children":[]}]}],"relativePath":"3.x/ru/extend/services/hash-crypt.md","filePath":"3.x/ru/extend/services/hash-crypt.md"}'),i={name:"3.x/ru/extend/services/hash-crypt.md"};function u(k,s,d,h,g,m){const e=a("pre-heading"),p=a("post-heading");return c(),o("div",null,[n(e),s[0]||(s[0]=l("h1",null,"Хеширование и шифрование",-1)),n(p),s[1]||(s[1]=r(`<h2 id="конфигурация"><a href="#конфигурация" class="header-anchor">#</a> Конфигурация</h2><p>При первой установке October для вас должен был быть сгенерирован случайный ключ. Вы можете убедиться в этом, проверив параметр <code>key</code> в конфигурационном файле <code>config/app.php</code>. Если ключ остаётся неизменённым, вам следует установить его в случайную строку длиной 32 символа. Если это значение не установлено должным образом, все зашифрованные значения будут небезопасны.</p><h2 id="хеширование"><a href="#хеширование" class="header-anchor">#</a> Хеширование</h2><p>Фасад <code>Hash</code> предоставляет безопасное хеширование Bcrypt для хранения паролей пользователей. Bcrypt является отличным выбором для хеширования паролей, потому что его «фактор нагрузки» настраивается, а это значит, что время, необходимое для генерации хеша, может быть увеличено по мере роста мощности оборудования.</p><p>Вы можете хешировать пароль, вызвав метод <code>make</code> фасада <code>Hash</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypassword&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В качестве альтернативы модели могут реализовать <a href="./../database/traits.html">трейт Hashable</a> для автоматического хеширования атрибутов.</p><h4 id="проверка-пароля-по-хешу"><a href="#проверка-пароля-по-хешу" class="header-anchor">#</a> Проверка пароля по хешу</h4><p>Метод <code>check</code> позволяет вам проверить, что данная строка открытого текста соответствует данному хешу.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">,</span> <span class="token variable">$hashedPassword</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// The passwords match...</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="проверка-необходимости-повторного-хеширования-пароля"><a href="#проверка-необходимости-повторного-хеширования-пароля" class="header-anchor">#</a> Проверка необходимости повторного хеширования пароля</h4><p>Функция <code>needsRehash</code> позволяет определить, изменился ли фактор нагрузки, используемый хешером, с момента хеширования пароля:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">needsRehash</span><span class="token punctuation">(</span><span class="token variable">$hashed</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$hashed</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="шифрование"><a href="#шифрование" class="header-anchor">#</a> Шифрование</h2><p>Вы можете зашифровать значение с помощью фасада <code>Crypt</code>. Все зашифрованные значения шифруются с использованием OpenSSL и шифра <code>AES-256-CBC</code>. Кроме того, все зашифрованные значения подписываются кодом аутентификации сообщения (MAC) для обнаружения любых модификаций зашифрованной строки.</p><p>Например, мы можем использовать метод <code>encrypt</code> для шифрования секрета и сохранения его в <a href="./../database/model.html">модели базы данных</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">secret</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">encrypt</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;shhh no telling&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="расшифровка-значения"><a href="#расшифровка-значения" class="header-anchor">#</a> Расшифровка значения</h4><p>Разумеется, вы можете расшифровать значения с помощью метода <code>decrypt</code> фасада <code>Crypt</code>. Если значение не может быть правильно расшифровано, например, когда MAC недействителен, будет выброшено исключение <code>Illuminate\\Contracts\\Encryption\\DecryptException</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Illuminate<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Encryption<span class="token punctuation">\\</span>DecryptException</span><span class="token punctuation">;</span>

<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token variable">$decrypted</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">decrypt</span><span class="token punctuation">(</span><span class="token variable">$encryptedValue</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">DecryptException</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В качестве альтернативы модели могут реализовать <a href="./../database/traits.html">трейт Encryptable</a> для автоматического шифрования и расшифровки атрибутов.</p>`,21))])}const f=t(i,[["render",u]]);export{y as __pageData,f as default};
